import React, { useState, useEffect } from 'react';
import { socket } from '../socket';
import { ConnectionState } from '../socket/ConnectionState';
import { ConnectionManager } from '../socket/ConnectionManager';
import { Events } from "../socket/Events";
import { MyForm } from '../socket/MyForm';

export default function App() {
  const [isConnected, setIsConnected] = useState(socket.connected);
  const [users, setUsers] = useState([]);
  const [fooEvents, setFooEvents] = useState([]);
  const [value, setValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    function onConnect() {
      setIsConnected(true)
    }

    function onDisconnect() {
      setIsConnected(false)
    }

    function onFooEvent(value) {
      setFooEvents(previous => [...previous, value])
    }

    socket.on('connect', onConnect);
    socket.on('disconnect', onDisconnect);
    socket.on('receive_message', onFooEvent);

    // alert("wwwww")
    socket.emit('usssers', { email: "wwwww", names: "www" }, (response) => {
      setIsLoading(false)
      console.log(response.status)
      // console.log("value")
    })

    socket.on("users", (ww) => {
      console.log(ww, "ww")
      setUsers(ww)

      for (let i = 0; i < ww.length; i++) {
        console.log(ww[i])
        const www = {
          user: ww[i],
          i: i,
        }
        // setUsers(ww[i], ...state.users)
      }
    })

    return () => {
      socket.off('connect', onConnect);
      socket.off('disconnect', onDisconnect);
      socket.off('receive_message', onFooEvent);
    };
  }, []);


  return (
    <div className="">
      {/* <button onClick={sendMessage}>send message</button> */}
      {/* Button to trigger sending a message */}
      <div className="" style={{ height: '70vh', width: '100%', flex: '1', margin: 'auto', display: 'block', backgroundColor: 'rgba(8, 58, 58, .9)' }}>
        <ConnectionState isConnected={isConnected} />
        <Events events={fooEvents} />
        <ConnectionManager />
        <MyForm />
      </div>
    </div>
  );
}